  by('aseWallSync').addEventListener('click',()=>{const live=by('liveVideo');if(live?.srcObject){by('aseWallRemote').srcObject=live.srcObject;by('aseWallRemote').play().catch(()=>{});by('aseWallRemoteNote').textContent='Showing a broadcast you explicitly opened in chat.';feedback('Opened LIVE stream mirrored.')}else feedback('Open and watch a consenting LIVE broadcaster in chat first.');});
