  by('aseCloseAllWindows').addEventListener('click',()=>{for(const el of floating.values())el.remove();floating.clear()});
  // Convenient slash command. Existing //CODEMENU and other commands pass through unchanged.
  by('messageForm').addEventListener('submit',e=>{const code=by('messageInput').value.trim().toUpperCase();const routes={'//COMMANDCENTER':'command','//ASEOPS':'command','//ASEEDITOR':'editor','//ASEVAULT':'vault','//SONAR':'sonar','//CCTVEDITOR':'clip','//DOSSIER':'profiles','//EVENTS':'timeline','//CAMERASTUDIO':'thermal','//SPECTRUM':'spectrum','//VIDEO-WALL':'wall'};if(routes[code]){e.preventDefault();e.stopImmediatePropagation();by('messageInput').value='';openSuite(routes[code])}},true);
