  const soundToggle=document.createElement('button');soundToggle.type='button';soundToggle.textContent=soundOn?'BEEPS ON':'BEEPS OFF';soundToggle.title='Toggle UI click and sonar sounds';soundToggle.style.cssText='font:10px monospace;min-width:70px;padding:5px';by('aseExit').before(soundToggle);soundToggle.addEventListener('click',()=>{soundOn=!soundOn;safeStore('ase-v29-sound',soundOn);soundToggle.textContent=soundOn?'BEEPS ON':'BEEPS OFF';feedback(soundOn?'Button sounds enabled':'Button sounds muted')});
  const volumeSlider=document.createElement('input');volumeSlider.type='range';volumeSlider.min=0;volumeSlider.max=100;volumeSlider.value=String(volume*100);volumeSlider.title='UI sound volume';volumeSlider.setAttribute('aria-label','Click sound volume');volumeSlider.style.cssText='width:70px;min-width:50px;flex:none';by('aseExit').before(volumeSlider);volumeSlider.addEventListener('input',e=>{volume=Number(e.target.value)/100;safeStore('ase-v29-volume',volume)});
  by('aseTilt').value=String(uiState.tilt||0);by('aseTilt').dispatchEvent(new Event('input'));
